import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry gelu_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 n
)
{
    .reg .u64 %rd<8>;
    .reg .u32 %r<8>;
    .reg .f32 %f<12>;
    .reg .pred %p<2>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r1, [n];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.u32 %r5, %r2, %r3, %r4;

    mov.u32 %r6, %nctaid.x;
    mul.lo.u32 %r7, %r6, %r3;

loop_top:
    setp.ge.u32 %p1, %r5, %r1;
    @%p1 bra loop_done;

    mul.wide.u32 %rd3, %r5, 4;
    add.s64 %rd4, %rd1, %rd3;
    ld.global.f32 %f1, [%rd4];

    mul.f32 %f2, %f1, %f1;
    mul.f32 %f3, %f2, %f1;
    mul.f32 %f4, %f3, 0.044715;
    add.f32 %f5, %f1, %f4;
    mul.f32 %f6, %f5, 0.7978845608;
    tanh.approx.f32 %f7, %f6;
    add.f32 %f8, %f7, 1.0;
    mul.f32 %f9, %f8, %f1;
    mul.f32 %f10, %f9, 0.5;

    add.s64 %rd5, %rd2, %rd3;
    st.global.f32 [%rd5], %f10;

    add.u32 %r5, %r5, %r7;
    bra loop_top;

loop_done:
    ret;
}
"""

_ptx_module = None


def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module


def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("gelu_kernel")


class ModelNew(nn.Module):
    """
    PTX-based implementation of the GELU (tanh approximation) activation
    used in minGPT, matching the reference Model exactly.
    """

    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x):
        assert x.is_cuda, "Input tensor must be on CUDA device"
        assert x.dtype == torch.float32, "Kernel specialized for float32 tensors"

        x_contig = x.contiguous()
        out = torch.empty_like(x_contig)

        n = x_contig.numel()

        module = _get_ptx_module()

        block_x = 256
        grid_x = (n + block_x - 1) // block_x

        module.launch(
            "gelu_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x_contig, out, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return out.view_as(x)

